// AssertContractContract runs every generated check against every declared subject.
//
//	Subjects: declare each with ContractSubject
//	Extend:   ContractOnWatch, ContractOnTrigger
//	Drop:     ContractWithout, by the path each check reports under
func AssertContractContract(t *testing.T, opts ...ContractOption) {
	t.Helper()
	cfg := newContractConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertContractContract was given no subject; declare one with " +
			"ContractSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("ContractWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runContractChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runContractChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runContractChecks(
	t *testing.T,
	cfg *contractConfig,
	label string,
	factory func() watcher.Contract,
	wrap func(tb testing.TB, subject watcher.Contract) watcher.Contract,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(contractWatch, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onWatch {
				cfg.run(t, string(suite.MethodID(contractWatch, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key)
				})
			}
		})

		t.Run(contractTrigger, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onTrigger {
				cfg.run(t, string(suite.MethodID(contractTrigger, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Key, cfg.Fixture.Value)
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through ContractWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

